"""검증용 venv의 버전 목록을 플랫폼 독립적인 editable 경로로 저장합니다."""

import subprocess
import sys
import sysconfig
from pathlib import Path

root = Path(__file__).resolve().parents[1]
result = subprocess.run(
    [
        sys.executable,
        "-m",
        "pip",
        "freeze",
        "--exclude-editable",
        "--path",
        sysconfig.get_path("purelib"),
    ],
    check=True,
    capture_output=True,
    text=True,
)
(root / "requirements-dev.lock").write_text(
    "# Generated by scripts/lock_dependencies.py; Python 3.12\n" + result.stdout + "-e .\n"
)
